import unittest
from pathlib import Path
from unittest.mock import patch

import dlthub_init.uv as uv


class IsolatedProjectEnvTest(unittest.TestCase):
    def test_strips_venv_hints_keeps_others(self):
        fake = {"VIRTUAL_ENV": "/a", "CONDA_PREFIX": "/b", "PYTHONPATH": "/c", "PATH": "/usr/bin"}
        with patch.dict("os.environ", fake, clear=True):
            env = uv._isolated_project_env()
        self.assertNotIn("VIRTUAL_ENV", env)
        self.assertNotIn("CONDA_PREFIX", env)
        self.assertNotIn("PYTHONPATH", env)
        self.assertEqual(env["PATH"], "/usr/bin")


class CommonUvPathsTest(unittest.TestCase):
    def test_returns_local_and_cargo_bin(self):
        paths = uv._common_uv_paths()
        names = {p.name for p in paths}
        self.assertTrue(names <= {"uv", "uv.exe"})
        self.assertTrue(any(".local" in p.parts for p in paths))
        self.assertTrue(any(".cargo" in p.parts for p in paths))


class FindUvTest(unittest.TestCase):
    def test_returns_path_when_on_path(self):
        with patch("dlthub_init.uv.shutil.which", return_value="/usr/local/bin/uv"):
            self.assertEqual(uv.find_uv(), "/usr/local/bin/uv")

    def test_falls_back_to_common_paths(self):
        with (
            patch("dlthub_init.uv.shutil.which", return_value=None),
            patch("dlthub_init.uv._common_uv_paths", return_value=()),
        ):
            self.assertIsNone(uv.find_uv())

    def test_finds_in_common_path_when_present(self):
        fake = Path("/tmp/does-not-matter/uv")
        with (
            patch("dlthub_init.uv.shutil.which", return_value=None),
            patch("dlthub_init.uv._common_uv_paths", return_value=(fake,)),
            patch.object(Path, "exists", return_value=True),
        ):
            self.assertEqual(uv.find_uv(), str(fake))


if __name__ == "__main__":
    unittest.main()

import tempfile
import unittest
from pathlib import Path

from dlthub_init.cli import main
from dlthub_init.uv import find_uv


@unittest.skipIf(find_uv() is None, "uv is not installed")
class EndToEndWorkspaceTest(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.project_dir = Path(self._tmp.name) / "ws"

    def tearDown(self):
        self._tmp.cleanup()

    def test_yes_scaffolds_and_syncs(self):
        self.assertEqual(main([str(self.project_dir), "--yes"]), 0)
        self.assertTrue((self.project_dir / "pyproject.toml").exists())
        self.assertTrue((self.project_dir / ".venv" / "pyvenv.cfg").exists())
        self.assertTrue((self.project_dir / ".agents" / "skills").is_dir())
        self.assertTrue((self.project_dir / ".mcp.json").exists())


if __name__ == "__main__":
    unittest.main()

import unittest
from unittest.mock import patch

import dlthub_init.display as display
from dlthub_init.prompts import confirm


class ConfirmTest(unittest.TestCase):
    def setUp(self):
        display.console.quiet = True
        interactive = patch("dlthub_init.prompts.stdin_is_interactive", return_value=True)
        interactive.start()
        self.addCleanup(interactive.stop)

    def tearDown(self):
        display.console.quiet = False

    @patch("dlthub_init.prompts.beaupy.select", return_value="Yes")
    def test_yes(self, _select):
        self.assertTrue(confirm("Proceed?"))

    @patch("dlthub_init.prompts.beaupy.select", return_value="No")
    def test_no(self, _select):
        self.assertFalse(confirm("Proceed?"))

    @patch("dlthub_init.prompts.beaupy.select", return_value="Yes")
    def test_default_controls_initial_cursor(self, select):
        confirm("Proceed?", default=False)
        self.assertEqual(select.call_args.kwargs["cursor_index"], 1)


class NonInteractiveConfirmTest(unittest.TestCase):
    def setUp(self):
        display.console.quiet = True
        non_interactive = patch("dlthub_init.prompts.stdin_is_interactive", return_value=False)
        non_interactive.start()
        self.addCleanup(non_interactive.stop)

    def tearDown(self):
        display.console.quiet = False

    @patch("dlthub_init.prompts.beaupy.select")
    def test_returns_default_without_prompting(self, select):
        self.assertTrue(confirm("Proceed?", default=True))
        self.assertFalse(confirm("Proceed?", default=False))
        select.assert_not_called()


if __name__ == "__main__":
    unittest.main()

import re
import unittest
from pathlib import Path

import dlthub_init.display as display
from dlthub_init.collisions import Outcome, PlannedPath

_ANSI = re.compile(r"\x1b\[[0-9;]*m")


def _capture(render) -> str:
    """Run a print function and return its output with ANSI styling stripped.

    rich emits color codes when stdout is a TTY (e.g. `make` in a terminal) but
    not when piped, so assertions must be style-agnostic.
    """
    with display.console.capture() as capture:
        render()
    return _ANSI.sub("", capture.get())


class PrintSummaryTest(unittest.TestCase):
    def _render(self, plan):
        return _capture(lambda: display.print_summary(plan))

    def test_groups_by_outcome(self):
        plan = [
            PlannedPath(Path("pyproject.toml"), Outcome.CREATE),
            PlannedPath(Path(".dlt/secrets.toml"), Outcome.SKIP),
            PlannedPath(Path(".gitignore"), Outcome.DISABLED),
        ]
        out = self._render(plan)
        self.assertIn("Created", out)
        self.assertIn("pyproject.toml", out)
        self.assertIn("already exist", out)
        self.assertIn("disabled by flag", out)

    def test_nothing_written_message_for_empty_plan(self):
        self.assertIn("nothing", self._render([]).lower())


class NextStepsTest(unittest.TestCase):
    def _render(self, project_dir, *, synced, uv_installed=True, interactive=True, skills_available=False):
        return _capture(
            lambda: display.print_next_steps(
                project_dir,
                synced=synced,
                uv_installed=uv_installed,
                interactive=interactive,
                skills_available=skills_available,
            )
        )

    def test_single_step_in_place_synced(self):
        out = self._render(Path.cwd(), synced=True)
        self.assertIn("Next step", out)
        self.assertNotIn("Next steps", out)
        self.assertNotIn("1.", out)
        self.assertNotIn("cd ", out)

    def test_multiple_steps_numbered_for_subdir(self):
        out = self._render(Path.cwd() / "sub", synced=False)
        self.assertIn("Next steps", out)
        self.assertIn("1.", out)
        self.assertIn("2.", out)
        self.assertIn("uv sync", out)

    def test_interactive_points_at_coding_agent(self):
        out = self._render(Path.cwd(), synced=True, interactive=True, skills_available=True)
        self.assertIn("Open your coding agent", out)
        self.assertNotIn(".agents/skills", out)

    def test_non_interactive_points_at_skills(self):
        out = self._render(Path.cwd(), synced=True, interactive=False, skills_available=True)
        self.assertIn(".agents/skills", out)
        self.assertNotIn("Open your coding agent", out)

    def test_non_interactive_without_skills_falls_back(self):
        out = self._render(Path.cwd(), synced=True, interactive=False, skills_available=False)
        self.assertIn("Open your coding agent", out)


class DisplayPathTest(unittest.TestCase):
    def test_cwd_is_dot(self):
        self.assertEqual(display._display_path(Path.cwd()), ".")


if __name__ == "__main__":
    unittest.main()
